    public class AccountGroupConfiguration : IEntityTypeConfiguration<AccountGroup>
    {
        public void Configure(EntityTypeBuilder<AccountGroup> builder)
        {
            builder.HasData(
                new AccountGroup() { Id = 1, Name = "Account Receivables", IsSubType = false, OpenBalance = false, TrackDepriciation = false, AccountClassificationId = 3 },
                new AccountGroup() { Id = 2, Name = "Other Current Assets", IsSubType = false, OpenBalance = false, TrackDepriciation = false, AccountClassificationId = 3 },
                new AccountGroup() { Id = 3, Name = "Bank", IsSubType = false, OpenBalance = false, TrackDepriciation = false, AccountClassificationId = 3 },
                new AccountGroup() { Id = 4, Name = "Fixed Assets", IsSubType = false, OpenBalance = false, TrackDepriciation = false, AccountClassificationId = 3 },
                new AccountGroup() { Id = 5, Name = "Other Assets", IsSubType = false, OpenBalance = false, TrackDepriciation = false, AccountClassificationId = 3 },
                new AccountGroup() { Id = 6, Name = "Accounts Payable (A/P)", IsSubType = false, OpenBalance = false, TrackDepriciation = false, AccountClassificationId = 4 },
                new AccountGroup() { Id = 7, Name = "Credit Card", IsSubType = false, OpenBalance = false, TrackDepriciation = false, AccountClassificationId = 4 },
                new AccountGroup() { Id = 8, Name = "Other Current Liabilities", IsSubType = false, OpenBalance = false, TrackDepriciation = false, AccountClassificationId = 4 },
                new AccountGroup() { Id = 9, Name = "Long Term Liabilities", IsSubType = false, OpenBalance = false, TrackDepriciation = false, AccountClassificationId = 4 },
                new AccountGroup() { Id = 10, Name = "Equity", IsSubType = false, OpenBalance = false, TrackDepriciation = false, AccountClassificationId = 3 },
                new AccountGroup() { Id = 11, Name = "Income", IsSubType = false, OpenBalance = false, TrackDepriciation = false, AccountClassificationId = 1 },
                new AccountGroup() { Id = 12, Name = "Other Income", IsSubType = false, OpenBalance = false, TrackDepriciation = false, AccountClassificationId = 1 },
                new AccountGroup() { Id = 13, Name = "Cost of Good Sold", IsSubType = false, OpenBalance = false, TrackDepriciation = false, AccountClassificationId = 1 },
                new AccountGroup() { Id = 14, Name = "Expenses", IsSubType = false, OpenBalance = false, TrackDepriciation = false, AccountClassificationId = 2 },
                new AccountGroup() { Id = 15, Name = "Other Expenses", IsSubType = false, OpenBalance = false, TrackDepriciation = false, AccountClassificationId = 2 },
                new AccountGroup() { Id = 101, ParentAccountGroupId = 1, AccountClassificationId = 3, Name = "Account Receivables", Description = "Accounts receivable (also called A/R, Debtors, or Trade and other receivables) tracks money that customers owe you for products or services, and payments customers make. System automatically creates one Accounts receivable account for you. Most businesses need only one. Each customer has a register, which functions like an Accounts receivable account for each customer.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 201, ParentAccountGroupId = 2, AccountClassificationId = 3, Name = "Allowance of Bad Debts", Description = "Use Allowance for bad debts to estimate the part of Accounts receivable you think you might not collect. Use this only if you are keeping your books on the accrual basis.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 202, ParentAccountGroupId = 2, AccountClassificationId = 3, Name = "Development Cost", Description = "Use Development costs to track amounts you deposit or set aside to arrange for financing, such as an SBA loan, or for deposits in anticipation of the purchase of property or other assets. When the deposit is refunded, or the purchase takes place, remove the amount from this account.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 203, ParentAccountGroupId = 2, AccountClassificationId = 3, Name = "Employee Cash Advances", Description = "Use Employee cash advances to track employee wages and salary you issue to an employee early, or other non-salary money given to employees. If you make a loan to an employee, use the Other current asset account type called Loans to others, instead.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 204, ParentAccountGroupId = 2, AccountClassificationId = 3, Name = "Inventory", Description = "Use Inventory to track the cost of goods your business purchases for resale. When the goods are sold, assign the sale to a Cost of goods sold account.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 205, ParentAccountGroupId = 2, AccountClassificationId = 3, Name = "Investment - Mortgage/Real Estate Loans", Description = "Use Investments - Mortgage/real estate loans to show the balances of any mortgage or real estate loans your business has made or purchased.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 206, ParentAccountGroupId = 2, AccountClassificationId = 3, Name = "Investment - Tax-Exempt Securities", Description = "Use Investments - Tax-exempt securities for investments in state and local bonds, or mutual funds that invest in state and local bonds.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 207, ParentAccountGroupId = 2, AccountClassificationId = 3, Name = "Investment - Government Obligations", Description = "Use Investments - U.S. government obligations for bonds issued by the U.S. government.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 208, ParentAccountGroupId = 2, AccountClassificationId = 3, Name = "Investments - Other", Description = "Use Investments - Other to track the value of investments not covered by other investment account types. Examples include publicly-traded stocks, coins, or gold.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 209, ParentAccountGroupId = 2, AccountClassificationId = 3, Name = "Loans To Officers", Description = "If you operate your business as a Limited Company, use Loans to officers to track money loaned to officers of your business.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 210, ParentAccountGroupId = 2, AccountClassificationId = 3, Name = "Loans to Others", Description = "Use Loans to others to track money your business loans to other people or businesses.This type of account is also referred to as Notes Receivable.For early salary payments to employees, use Employee cash advances, instead.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 211, ParentAccountGroupId = 2, AccountClassificationId = 3, Name = "Loans to Stockholders", Description = "If you operate your business as a Limited, use Loans to stockholders to track money your business loans to its stockholders.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 212, ParentAccountGroupId = 2, AccountClassificationId = 3, Name = "Other Current Assets", Description = "Use Other current assets for current assets not covered by the other types. Current assets are likely to be converted to cash or used up in a year.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 213, ParentAccountGroupId = 2, AccountClassificationId = 3, Name = "Prepaid Expenses", Description = "Use Prepaid expenses to track payments for expenses that you won’t recognize until your next accounting period. When you recognize the expense, make a journal entry to transfer money from this account to the expense account.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 214, ParentAccountGroupId = 2, AccountClassificationId = 3, Name = "Retainage", Description = "Use Retainage if your customers regularly hold back a portion of a contract amount until you have completed a project. This type of account is often used in the construction industry, and only if you record income on an accrual basis.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 215, ParentAccountGroupId = 2, AccountClassificationId = 3, Name = "Undeposited Funds", Description = "Use Undeposited funds for cash or checks from sales that haven’t been deposited yet. For petty cash, use Cash on hand, instead.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 301, ParentAccountGroupId = 3, AccountClassificationId = 3, Name = "Cash on hand", Description = "Use a Cash on hand account to track cash your company keeps for occasional expenses, also called petty cash. To track cash from sales that have not been deposited yet, use a pre-created account called Undeposited funds, instead.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 302, ParentAccountGroupId = 3, AccountClassificationId = 3, Name = "Checking", Description = "Use Checking accounts to track all your checking activity, including debit card transactions. Each checking account your company has at a bank or other financial institution should have its own Checking type account in system.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 303, ParentAccountGroupId = 3, AccountClassificationId = 3, Name = "Money Market", Description = "Use Money market to track amounts in money market accounts. For investments, see Other Current Assets, instead.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 304, ParentAccountGroupId = 3, AccountClassificationId = 3, Name = "Rents Held in Trust", Description = "Use Rents held in trust to track deposits and rent held on behalf of the property owners. Typically only property managers use this type of account.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 305, ParentAccountGroupId = 3, AccountClassificationId = 3, Name = "Savings", Description = "Use Savings accounts to track your savings and CD activity. Each savings account your company has at a bank or other financial institution should have its own Savings type account. For investments, see Other Current Assets, instead.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 306, ParentAccountGroupId = 3, AccountClassificationId = 3, Name = "Trust account", Description = "Use Trust accounts for money held by you for the benefit of someone else. For example, trust accounts are often used by attorneys to keep track of expense money their customers have given them. Often, to keep the amount in a trust account from looking like it’s yours, the amount is offset in a 'contra' liability account (a Current Liability).", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 307, ParentAccountGroupId = 3, AccountClassificationId = 3, Name = "Undeposited Fund", Description = "Undeposited Funds, keep all undeposited cheques, drafts and bank documents", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 401, ParentAccountGroupId = 4, AccountClassificationId = 3, Name = "Accumulated Amortization", Description = "Use Accumulated amortization to track how much you amortize intangible assets.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 402, ParentAccountGroupId = 4, AccountClassificationId = 3, Name = "Accumulated Depletion", Description = "Use Accumulated depletion to track how much you deplete a natural resource.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 403, ParentAccountGroupId = 4, AccountClassificationId = 3, Name = "Accumulated Depreciation", Description = "Use Accumulated depreciation to track how much you depreciate a fixed asset (a physical asset you do not expect to convert to cash during one year of normal operations).", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 404, ParentAccountGroupId = 4, AccountClassificationId = 3, Name = "Buildings", Description = "Use Buildings to track the cost of structures you own and use for your business. If you have a business in your home, consult your accountant or IRS Publication 587. Use a Land account for the land portion of any real property you own, splitting the cost of the property between land and building in a logical method. A common method is to mimic the land-to-building ratio on the property tax statement.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 405, ParentAccountGroupId = 4, AccountClassificationId = 3, Name = "Depletable Assets", Description = "Use Depletable assets to track natural resources, such as timberlands, oil wells, and mineral deposits.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 406, ParentAccountGroupId = 4, AccountClassificationId = 3, Name = "Furniture & Fixtures", Description = "Use Furniture & fixtures to track any furniture and fixtures your business owns and uses, like a dental chair or sales booth.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 407, ParentAccountGroupId = 4, AccountClassificationId = 3, Name = "Intangible Assets", Description = "Use Intangible assets to track intangible assets that you plan to amortize. Examples include franchises, customer lists, copyrights, and patents.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 408, ParentAccountGroupId = 4, AccountClassificationId = 3, Name = "Land", Description = "Use Land for land or property you don’t depreciate.If land and building were acquired together, split the cost between the two in a logical way. One common method is to use the land-to-building ratio on the property tax statement. For land you use as a natural resource, use a Depletable assets account, instead.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 409, ParentAccountGroupId = 4, AccountClassificationId = 3, Name = "Leasehold Improvements", Description = "Use Leasehold improvements to track improvements to a leased asset that increases the asset’s value. For example, if you carpet a leased office space and are not reimbursed, that’s a leasehold improvement.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 410, ParentAccountGroupId = 4, AccountClassificationId = 3, Name = "Machinery & Equipment", Description = "Use Machinery & equipment to track computer hardware, as well as any other non-furniture fixtures or devices owned and used for your business. This includes equipment that you ride, like tractors and lawn mowers. Cars and trucks, however, should be tracked with Vehicle accounts, instead.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 411, ParentAccountGroupId = 4, AccountClassificationId = 3, Name = "Other fixed assets", Description = "Use Other fixed asset for fixed assets that are not covered by other asset types. Fixed assets are physical property that you use in your business and that you do not expect to convert to cash or be used up during one year of normal operations.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 412, ParentAccountGroupId = 4, AccountClassificationId = 3, Name = "Vehicles", Description = "Use Vehicles to track the value of vehicles your business owns and uses for business. This includes off-road vehicles, air planes, helicopters, and boats. If you use a vehicle for both business and personal use, consult your accountant or the IRS to see how you should track its value.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 501, ParentAccountGroupId = 5, AccountClassificationId = 3, Name = "Accumulated Amortization of Other Assets", Description = "Use Accumulated amortization of other assets to track how much you’ve amortized asset whose type is Other Asset.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 502, ParentAccountGroupId = 5, AccountClassificationId = 3, Name = "Goodwill", Description = "Use Goodwill only if you have acquired another company. It represents the intangible assets of the acquired company which gave it an advantage, such as favorable government relations, business name, outstanding credit ratings, location, superior management, customer lists, product quality, or good labor relations.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 503, ParentAccountGroupId = 5, AccountClassificationId = 3, Name = "Lease Buyout", Description = "Use Lease buyout to track lease payments to be applied toward the purchase of a leased asset. You don’t track the leased asset itself until you purchase it.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 504, ParentAccountGroupId = 5, AccountClassificationId = 3, Name = "Licenses", Description = "Use Licenses to track non-professional licenses for permission to engage in an activity, like selling alcohol or radio broadcasting. For fees associated with professional licenses granted to individuals, use a Legal & professional fees expense account, instead.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 505, ParentAccountGroupId = 5, AccountClassificationId = 3, Name = "Organizational Costs", Description = "Use Organizational costs to track costs incurred when forming a partnership or corporation. The costs include the legal and accounting costs necessary to organize the company, facilitate the filings of the legal documents, and other paperwork.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 506, ParentAccountGroupId = 5, AccountClassificationId = 3, Name = "Other Long-term Assets", Description = "Use Other long-term assets to track assets not covered by other types. Long-term assets are expected to provide value for more than one year.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 507, ParentAccountGroupId = 5, AccountClassificationId = 3, Name = "Security Deposits", Description = "Use Security deposits to track funds you’ve paid to cover any potential costs incurred by damage, loss, or theft. The funds should be returned to you at the end of the contract. If you collect deposits, use an Other current liabilities account type (an Other current liability account).", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 601, ParentAccountGroupId = 6, AccountClassificationId = 4, Name = "Accounts Payable (A/P)", Description = "Accounts payable (also called A/P) tracks amounts you owe to your vendors and suppliers. Systen automatically creates one Accounts Payable account for you. Most businesses need only one.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 602, ParentAccountGroupId = 6, AccountClassificationId = 4, Name = "Employees", Description = "Accounts payable tracks amounts you owe to your Employees.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 701, ParentAccountGroupId = 7, AccountClassificationId = 4, Name = "Credit Card", Description = "Credit card accounts track the balance due on your business credit cards. Create one Credit card account for each credit card account your business uses", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 801, ParentAccountGroupId = 8, AccountClassificationId = 4, Name = "Federal Income Tax Payable", Description = "Use Federal Income Tax Payable if your business is a corporation, S corporation, or limited partnership keeping records on the accrual basis.This account tracks income tax liabilities in the year the income is earned.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 802, ParentAccountGroupId = 8, AccountClassificationId = 4, Name = "Insurance Payable", Description = "Use Insurance payable to keep track of insurance amounts due. This account is most useful for businesses with monthly recurring insurance expenses such as Workers’ Compensation.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 803, ParentAccountGroupId = 8, AccountClassificationId = 4, Name = "Line of Credit", Description = "Use Line of credit to track the balance due on any lines of credit your business has. Each line of credit your business has should have its own Line of credit account.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 804, ParentAccountGroupId = 8, AccountClassificationId = 4, Name = "Loan Payable", Description = "Use Loan payable to track loans your business owes which are payable within the next twelve months. For longer-term loans, use the Long-term liability called Notes payable, instead.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 805, ParentAccountGroupId = 8, AccountClassificationId = 4, Name = "Other Current Liabilities", Description = "Use Other current liabilities to track liabilities due within the next twelve months that do not fit the Other current liability account types.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 806, ParentAccountGroupId = 8, AccountClassificationId = 4, Name = "Payroll Clearing", Description = "Use Payroll clearing to keep track of any non-tax amounts that you have deducted from employee paychecks or that you owe as a result of doing payroll. When you forward money to the appropriate vendors, deduct the amount from the balance of this account. Do not use this account for tax amounts you have withheld or owe from paying employee wages. For those amounts, use the Payroll tax payable account instead.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 807, ParentAccountGroupId = 8, AccountClassificationId = 4, Name = "Payroll Tax Payable", Description = "Use Payroll tax payable to keep track of tax amounts that you owe to Federal, State, and Local government agencies as a result of paying wages and taxes you have withheld from employee paychecks. When you forward the money to the government agency, deduct the amount from the balance of this account.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 808, ParentAccountGroupId = 8, AccountClassificationId = 4, Name = "Prepaid Expenses Payable", Description = "Use Prepaid expenses payable to track items such as property taxes that are due, but not yet deductible as an expense because the period they cover has not yet passed.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 809, ParentAccountGroupId = 8, AccountClassificationId = 4, Name = "Rents in trust - Liability", Description = "Use Rents in trust - liability to offset the Rents in trust amount in assets. Amounts in these accounts are held by your business on behalf of others. They do not belong to your business, so should not appear to be yours on your balance sheet. This 'contra' account takes care of that, as long as the two balances match.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 810, ParentAccountGroupId = 8, AccountClassificationId = 4, Name = "Sales Tax Payable", Description = "Use Sales tax payable to track sales tax you have collected, but not yet remitted to the IRS.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 811, ParentAccountGroupId = 8, AccountClassificationId = 4, Name = "State/Local Income Tax Payable", Description = "Use State/local income tax payable if your business is a corporation, S corporation, or limited partnership keeping records on the accrual basis. This account tracks income tax liabilities in the year the income is earned", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 812, ParentAccountGroupId = 8, AccountClassificationId = 4, Name = "Trust Accounts - Liabilities", Description = "Use Trust accounts - liabilities to offset Trust accounts in assets.Amounts in these accounts are held by your business on behalf of others. They do not belong to your business, so should not appear to be yours on your balance sheet. This 'contra' account takes care of that, as long as the two balances match.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 813, ParentAccountGroupId = 8, AccountClassificationId = 4, Name = "Integrated Income Tax Payable", Description = "Use Integrated income tax payable if your business is a corporation, S corporation, or limited partnership keeping records on the accrual basis. This account tracks income tax liabilities in the year the income is earned", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 901, ParentAccountGroupId = 9, AccountClassificationId = 4, Name = "Notes Payable", Description = "Use Notes payable to track the amounts your business owes in long-term (over twelve months) loans. For shorter loans, use the Other current liability account type called Loan payable, instead.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 902, ParentAccountGroupId = 9, AccountClassificationId = 4, Name = "Other Long Term Liabilities", Description = "Use Other long term liabilities to track liabilities due in more than twelve months that don’t fit the other Long-term liability account types.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 903, ParentAccountGroupId = 9, AccountClassificationId = 4, Name = "Shareholder Notes Payable", Description = "Use Shareholder notes payable to track long-term loan balances your business owes its shareholders.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 1001, ParentAccountGroupId = 10, AccountClassificationId = 3, Name = "Accumulated Adjustment", Description = "S corporations use this account to track adjustments to owner’s equity that are not attributable to net income.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 1002, ParentAccountGroupId = 10, AccountClassificationId = 3, Name = "Common Stock", Description = "Corporations use Common stock to track shares of its common stock in the hands of shareholders. The amount in this account should be the stated (or par) value of the stock.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 1003, ParentAccountGroupId = 10, AccountClassificationId = 3, Name = "Opening Balance Equity", Description = "System creates this account the first time you enter an opening balance for a balance sheet account. As you enter opening balances, System records the amounts in Opening balance equity. This ensures that you have a correct balance sheet for your company, even before you’ve finished entering all your company’s assets and liabilities.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 1004, ParentAccountGroupId = 10, AccountClassificationId = 3, Name = "Owner\'s Equity", Description = "S corporations use Owner’s equity to show the cumulative net income or loss of their business as of the beginning of the fiscal year. ", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 1005, ParentAccountGroupId = 10, AccountClassificationId = 3, Name = "Paid-In Capital or Surplus", Description = "Corporations use Paid-in capital to track amounts received from shareholders in exchange for stock that are over and above the stock’s stated (or par) value.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 1006, ParentAccountGroupId = 10, AccountClassificationId = 3, Name = "Partner Contributions", Description = "Partnerships use Partner contributions to track amounts partners contribute to the partnership during the year.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 1007, ParentAccountGroupId = 10, AccountClassificationId = 3, Name = "Partner Distributions", Description = "Partnerships use Partner distributions to track amounts distributed by the partnership to its partners during the year. Don’t use this for regular payments to partners for interest or service. For regular payments, use a Guaranteed payments account (a Expense account in Payroll expenses), instead. ", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 1008, ParentAccountGroupId = 10, AccountClassificationId = 3, Name = "Partner\'s Equity", Description = "Partnerships use Partner’s equity to show the income remaining in the partnership for each partner as of the end of the prior year.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 1009, ParentAccountGroupId = 10, AccountClassificationId = 3, Name = "Preferred Stock", Description = "Corporations use this account to track shares of its preferred stock in the hands of shareholders. The amount in this account should be the stated (or par) value of the stock.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 1010, ParentAccountGroupId = 10, AccountClassificationId = 3, Name = "Retained Earnings", Description = "System adds this account when you create your company. Retained earnings tracks net income from previous fiscal years. System automatically transfers your profit (or loss) to Retained earnings at the end of each fiscal year.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 1011, ParentAccountGroupId = 10, AccountClassificationId = 3, Name = "Treasury Stock", Description = "Corporations use Treasury stock to track amounts paid by the corporation to buy its own stock back from shareholders.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 1101, ParentAccountGroupId = 11, AccountClassificationId = 1, Name = "Discounts/Refunds Given", Description = "Use Discounts/refunds given to track discounts you give to customers. This account typically has a negative balance so it offsets other income. For discounts from vendors, use an expense account, instead.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 1102, ParentAccountGroupId = 11, AccountClassificationId = 1, Name = "Non-Profit Income", Description = "Use Non-profit income to track money coming in if you are a non-profit organization.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 1103, ParentAccountGroupId = 11, AccountClassificationId = 1, Name = "Other Primary Income", Description = "Use Other primary income to track income from normal business operations that doesn’t fall into another Income type.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 1104, ParentAccountGroupId = 11, AccountClassificationId = 1, Name = "Sales of Product Income", Description = "Use Sales of product income to track income from selling products. This can include all kinds of products, like crops and livestock, rental fees, performances, and food served.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
                new AccountGroup() { Id = 1105, ParentAccountGroupId = 11, AccountClassificationId = 1, Name = "Service/Fee Income", Description = "Use Service/fee income to track income from services you perform or ordinary usage fees you charge. For fees customers pay you for late payments or other uncommon situations, use an Other Income account type called Other miscellaneous income, instead.", IsSubType = true, OpenBalance = false, TrackDepriciation = false },
